WITH remaining_keys AS (SELECT customer_id, device FROM sessions EXCEPT SELECT customer_id, device FROM sessions WHERE device = 'tablet'), verified AS (SELECT s.* FROM sessions s JOIN remaining_keys k ON s.customer_id = k.customer_id AND s.device = k.device) SELECT s.id, s.customer_id, s.device, s.browser, CASE WHEN browser RLIKE '^(Chrome|Safari)$' THEN 'EXTENDED' WHEN browser RLIKE '^(Firefox|Edge)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS browser_zone, (SELECT AVG(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS avg_subscription_monthly_fee FROM verified s ORDER BY browser;
